insert into public.publishers (exhibitor_no, booth_number, original_booth_number, name, name_en, country_ko, country_en, is_special, categories, introduction, homepage, instagram, sort_order) values
  (147, 'A2003', null, '도서출판 폭스코너', 'Foxcorner Publishing House', null, null, false, array['문학','전자출판','기타(인문교양)']::text[], '''지혜로운 여우가 책을 읽는 모퉁이'' 도서출판 폭스코너입니다. 폭스코너는 2015년 편집자 두 명이 의기투합해 만든 출판사로, 현재까지 85종의 책을 출간하였습니다. 소설과 에세이, 청소년소설 등의 문학 서적과 학교 선생님들과 손잡고 만든 인문교양서가 대표적이며, 웹소설 시리즈 및 육아 관련 서적도 다수 출간하였습니다. 세상에 도움이 될 수 있는 책이 무엇일지 항상 고민하며 앞으로도 인기에 연연하지 않는 좋은 책을 출간하기 위해 노력할 것입니다.', null, 'https://www.instagram.com/foxcorner15/', 147),
  (148, 'A2003', null, '도서출판 다독다독', 'Dadokdadok Publishing', null, null, false, array['기타(요리','자녀교육','취미','교양)']::text[], '다독다독 출판사는 ‘일상의 작은 변화에서 시작되는 진정한 행복’이라는 믿음을 바탕으로 요리·자녀교육·예술을 축으로 삶의 밀도를 높이는 책을 만듭니다. 『프랑스 가정식 오븐 요리』, 『파스타꼬레』 등 요리책은 조리를 넘어 미식의 기록과 식탁의 기쁨을 담아내고, 『돈 걱정 없는 육아』, 『미라클 베드타임』, 『외동아이 이렇게 키웠습니다』는 실천 가능한 조언과 현실적인 사례로 각 가정에 맞는 양육의 기준을 제시합니다. 『컬러링하며 세계 카페 여행』, 『미술관 컬러링북』, 『화가가 사랑한 파리 미술관』은 가벼운 시작으로 이어지는 예술 경험을 통해 자신만의 감각과 취향을 발견하도록 안내합니다.', null, 'https://www.instagram.com/dadokbooks/', 148),
  (149, 'A2004', null, '안온북스', 'anonbooks', null, null, false, array['예술','문학']::text[], '안온북스는 독자의 시간을 안온하게 지키는 책, 그리고 아직 우리에게 도달하지 않은 불온한 문학을 발견하고 소개하는 출판사입니다. 2021년 창립 이후 50종 이상의 도서를 출간하며 소설과 에세이를 중심으로 한국문학의 현재를 담아왔고, 예술적 영감을 확장하는 다양한 콘텐츠를 함께 선보이고 있습니다. 김혼비 산문집 다정소감, 정세랑 소설 아라의 소설, 최진영 소설 쓰게 될 것, 윤가은 각본집 세계의 주인 등 동시대 작가들의 작품을 통해 독자와 꾸준히 만나왔습니다. 안온북스는 신인과 젊은 작가에게는 새로운 기회를 제공하는 파트너로, 한국문학을 사랑하는 독자에게는 오래 곁에 두고 싶은 믿을 만한 친구로 자리하고자 합니다. 이번 도서전에서도 단단하고 다정한 책들로 찾아뵙겠습니다. 감사합니다.', 'http://www.anonbooks.net/main/index.php', 'https://www.instagram.com/anonbooks_publishing/', 149),
  (150, 'A2005', null, '청미출판사', 'CHEONGMI PUBLISHING CO.', null, null, false, array['철학','사회과학','문학']::text[], '청미출판사는 ‘호모 헌드레드’ 시대를 살아가는 우리에게 “인간이란 무엇이며, 좋은 삶이란 무엇인가?”를 질문합니다. 우리는 책을 사람들이 만나 소통하는 ‘광장’으로 여기며, 그 안에서 삶의 의미를 성찰하는 인문학을 지향합니다. 2015년부터 철학, 사회학, 문학을 중심으로 나이듦, 은퇴, 죽음, 고독을 깊이 있게 다룬 30여 종의 책을 펴냈습니다. 대표 도서로는 엘리자베스 퀴블러 로스의 『죽음과 죽어감』, 에바 일루즈의 『해피크라시』, 라르스 스벤젠의 『외로움의 철학』 등이 있습니다. 청미는 삶의 모든 과정에 깊이 있는 질문을 던집니다.', 'https://blog.naver.com/cheongmipub', null, 150),
  (151, 'A2006', null, '(주)학지사', 'Hakjisa Co.', null, null, false, array['사회과학','전자출판']::text[], 'HCG 학지사는 1992년 설립한 종합 콘텐츠 그룹으로 대학교재 전문 출판사입니다. 심리학, 교육학 을 포함한 사회과학 분야의 도서들과, 간호, 보건 계열의 도서들을 출판하고 있습니다. 캠퍼스북은 대학생과 교육 현장을 위한 전자책 기반 학습 플랫폼으로, 국내 주요 출판사의 전공교양 교재를 디지털 환경에 최적화해 제공합니다. 언제 어디서나 가볍게 학습할 수 있는 접근성과 합리적인 가격, 그리고 학습 효율을 높이는 다양한 기능을 통해 학생과 교육기관 모두에게 새로운 학습 경험을 제시하며, 종이책을 넘어선 스마트한 캠퍼스 라이프를 만들어가고 있습니다.', 'https://hakjisa.co.kr', null, 151),
  (152, 'A2007', null, '잉글리시에그', 'ENGLISHEGG', null, null, false, array['아동']::text[], '잉글리시에그는 아이들의 일상이, 놀이가, 생각이 자연스럽게 영어로 표현되며 영어를 즐길 수 있게 되는 것을 목표로 합니다. 기존의 주입식 영어교육에서 탈피하여, 아이들이 모국어를 습득하는 것과 동일한 방법으로 자연스럽게 일상 속에서 영어를 접하고 재미있게 익힐 수 있도록 잉글리시에그만의 독자적인 교재 및 교구를 개발하였습니다. 또한, 잉글리시에그는 올바른 교육에 대한 마음은 타협하지 않는다는 신념 하나로, 단순히 언어만 익히는 것이 아니라 영유아 발달 시기에 맞춰 감성과 인성 발달 영역까지도 다룬 프리미엄 영유아 영어교육입니다.', 'http://www.englishegg.co.kr', 'https://www.instagram.com/englishegg_gangdong/', 152),
  (153, 'A2008', null, '우리나비', 'Woorinabi Publishing Co.', null, null, false, array['문학','아동','기타(그래픽노블)']::text[], '''봄날의 고양이처럼 따사롭고 정겨운 책''을 만들겠다는 마음으로 첫발을 뗐습니다. 무한 경쟁과 디지털 정보가 범람하는 시대일수록, 손끝에 닿는 종이책의 질감과 그래픽노블 특유의 깊이 있는 예술성에 주목합니다. 우리나비는 이러한 책의 물성을 빌려 사라져가는 소중한 기록과 우리의 역사를 그래픽노블이라는 현대적 매체로 복원하고, 문화다양성의 가치를 기록합니다. 단편적인 정보를 넘어 시각적 감동과 서사의 힘이 결합된 그래픽노블로, 삶을 관통하는 통찰과 치유를 공유하고자 합니다.', 'http://www.woorinabi.com', 'https://www.instagram.com/woorinabipublishing_co/', 153),
  (154, 'A2009', null, '한국출판문화산업진흥원', 'Publication Industry Promotion Agency of Korea', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '한국출판문화산업진흥원이 운영하는 출판지식창업보육센터는 출판 분야의 예비 창업자와 초기 창업 출판사의 안정적 성장을 함께하는 공간입니다. 20여 개 출판사가 입주해 아동과 성인을 위한 종이책, 전자책, 오디오북 등 다양한 형태의 콘텐츠를 만들며 각자의 이야기를 세상에 전하고 있습니다. 센터는 창작과 제작이 이루어지는 작업 공간을 비롯해, 출판 기획, 제작, 유통, 저작권, 디지털 전환 전반에 대한 교육과 컨설팅을 통해 창작과 경영의 고민을 실제 성과로 연결합니다. 또한 출판사 간 교류와 협업을 통해 새로운 시도와 연결이 자연스럽게 이루어지는 환경을 만들어가고 있습니다. 새로운 목소리가 지속 가능한 출판으로 이어지도록, 출판지식창업보육센터는 오늘도 출판의 가능성을 키워가고 있습니다.', 'http://www.kpipa.or.kr', 'https://www.instagram.com/kpipaorkr/', 154),
  (155, 'A2009', null, '그리모어', 'Grimoire', null, null, false, array['예술','문학']::text[], '콜록콜록! 먼지 덮인 종이 뭉치, 서랍 속 낡은 원고, 일상의 틈에 끼인 메모. 아직 책이 되지 못한 텍스트가 있습니다. 그리모어는 이 조각들을 모아 한 권의 책으로 엮어냅니다. 조금 이상하고 기묘해도 상관없습니다. 이론과 비평, 장르문학, 에세이까지, 어딘가에 아직 풀리지 않은 마법이 남아있습니다. 흥미로운 이야기를 찾아 첫 페이지를 넘겨 보세요. 첫 번째 책은 지하철이라는 가장 반복적인 일상 속에서 건져 올린 에세이입니다.', 'https://x.com/grimoire_kr', null, 155),
  (156, 'A2009', null, '나무의말', 'Words of Trees', null, null, false, array['아동']::text[], '나무의말은 질문하는 이야기, 마음을 들여다보는 이야기, 함께 살아가는 이야기, 그리고 상상하는 이야기를 만드는 그림책 출판사입니다. 어린이와 어른 모두의 마음에 닿는 이야기를 통해 감정과 관계, 세계를 새롭게 바라보는 경험을 전하고자 합니다. 한 권의 책이 삶을 다정하게 비추는 작은 창이 되기를 바라며, 읽는 이를 스스로 질문하고 돌아보게 하는 그림책을 꾸준히 펴내고 있습니다.', null, 'https://www.instagram.com/words.of.trees/', 156),
  (157, 'A2009', null, '다정한시민', 'Friendly Citizen', null, null, false, array['아동']::text[], '다정한시민 출판사는 모두가 존엄한 세상을 꿈꾸며 어린이, 청소년 책을 만듭니다. 어린이책으로 장애, 차별, 동물권, 평등, 가난 등 사회적 약자에게 어떻게 대해야 하는지 배우는 [다정한 하루] 시리즈와 기후 위기로 멸종 위기에 처한 동물들을 소개하는 [생명을 대하는 자세] 시리즈를 내고 있습니다. 청소년책으로 대멸종, 에너지, 생태전환디자인, 지리학 등 세상을 바꾸기 위한 우리의 역할을 생각하는 [질문하는 시민] 시리즈를 내고 있습니다.', 'http://blog.naver.com/dasibooks', null, 157),
  (158, 'A2009', null, '도서출판 11%', '11% Publishing', null, null, false, array['사회과학','예술','학습참고서']::text[], '“세상에서 가장 정확한 출판사” 도서출판 11%입니다. 저희는 ‘저자에게 공정한 수익을, 독자에게 투명한 가치를’ 전한다는 미션 아래, 저자와 대등한 파트너로서 협력합니다. 그 상생의 약속을 위해 모든 저자에게 기본 11%의 인세를 보장합니다. 또한 세계 최초 저작권 보호 앱 ‘11프로텍터’를 개발하여, 모든 인쇄 도서의 인세를 투명하게 추적하고 정직하게 지급합니다. (Apple 앱스토어/Google Play 스토어 다운로드 가능) 도서출판 11%는 혁신과 신뢰를 바탕으로 지속 가능한 출판 생태계를 선도해 나가겠습니다.', 'http://11pro.kr', null, 158),
  (159, 'A2009', null, '도서출판 어웨이크', 'AWAKE PUBLISHING HOUSE', null, null, false, array['철학','사회과학','언어']::text[], '도서출판 어웨이크(AWAKE)는 2025년 9월에 첫 책을 선보인 신생 출판사입니다. "나를 일으켜 세우는 세상의 모든 지식"을 마음에 새기며, 하루하루 자신을 돌보고 가치를 발견하며 성장을 멈추지 않는 사람들을 위해 인문·심리·자기계발·에세이 분야의 다양한 삶의 지혜와 기술을 제안합니다. 좋은 책 한 권이 사람의 생각을 흔들고 삶의 방향을 바꿀 수 있다고 믿습니다. 내 삶의 운전대를 잡고 모험을 떠나는 모든 분들에게 든든한 이정표가 되고자 합니다. AI가 일상이 된 시대에도 책은 사람을 깨우는 가장 깊은 언어입니다. 도서출판 어웨이크는 AI 문명 속에서도 책과 사람을 잇는 가교로서 독자들과 함께 성장해 나가겠습니다.', null, 'https://www.instagram.com/awakebooks.kr/', 159),
  (160, 'A2009', null, '문학정원', 'Munhak Garden', null, null, false, array['문학']::text[], '문학정원은 2015년 단편소설 「미루나무 등대」로 김유정 신인문학상을 수상하고, 2023년 제3회 넥서스 경장편 작가상 대상을 받으며 독보적인 서사 세계를 구축해온 서경희 작가가 설립한 1인 작가 출판사입니다. ''작가주의 출판''을 표방하며 2021년 문을 연 이래, 우리 사회의 이면과 소외된 목소리를 문학의 중심부로 끌어올리는 작업을 이어오고 있습니다. 『수박 맛 좋아』와 『복도식 아파트』를 통해 한국 사회의 부동산 문제를 정면으로 응시했으며, 『하리』에서는 미혼모 문제를, 소설집 『밤의 독백』에서는 소시민과 약자의 삶을 밀도 있게 그려냈습니다. 문학정원은 화려한 일상에 가려진 낮고 외진 곳의 목소리에 집중하며, 삶을 관통하는 날카로운 질문을 던지는 소설을 꾸준히 선보이고자 합니다.', null, 'https://www.instagram.com/ru_dadadadada/', 160),
  (161, 'A2009', null, '빅퀘스천 출판사', 'Big Questions Publishing Co.', null, null, false, array['문학','역사','아동']::text[], '빅퀘스천 출판사가 생각하는 세상에서 가장 위대한 질문은 ‘사람’입니다. 사람들에게 더 재미있고 유익한 삶을 사는 데 도움이 되는 책을 만듭니다. 2024년 출판사 설립 이후 현재까지 , , , 등을 출간하였습니다.', null, 'https://www.instagram.com/bigqns2024/', 161),
  (162, 'A2009', null, '스타라잇 출판사', 'Starlight books', null, null, false, array['총류','기타(에세이','교육 서적)']::text[], '스타라잇 출판사는 별빛처럼 한 문장, 한 글귀가 독자의 영혼을 환히 비출 수 있다는 믿음에서 시작되었습니다. 교육서와 에세이를 중심으로, 삶에 깊은 울림과 사유를 더하는 책을 꾸준히 출간하고 있으며, 독자 한 분 한 분의 마음에 오래 남는 가치를 전하고자 힘쓰고 있습니다. 세종도서에 선정된 도서를 비롯하여, 대부분의 출간 도서는 한국출판진흥원의 지원 사업에 선정되었으며, 이를 통해 오디오북과 전자책으로도 제작되어 더 많은 독자와 다양한 방식으로 만나고 있습니다. 앞으로도 스타라잇 출판사는 시대의 변화 속에서도 사람의 내면을 밝히는 책을 정성껏 선보이겠습니다.', 'https://www.youtube.com/@momsradio', 'https://www.instagram.com/youtube/', 162),
  (163, 'A2009', null, '아트레이크 출판사', 'ARTLAKE Inc', null, null, false, array['총류','예술','문학']::text[], '아트레이크(ARTLAKE)는 한국의 아름다운 미술, 음악, 전통을 세계에 알리기 위해 설립된 출판사입니다. 고유한 한국의 미(美)를 탐구하며 전통과 현대를 아우르는 깊이 있는 책을 펴냅니다. 한국을 소개하는 사진 작품집, 국립중앙박물관과 K-헤리티지, 한국 고유의 정원, 전통 기법을 잇는 현대 화가, 그리고 ''씻김굿''에 이르기까지 다채로운 문화 예술을 책에 담아냅니다. 더불어 SBS ''고래와 나'' 같은 환경 보호, AI 시대를 대비하는 문학, 위로를 주는 차(茶)의 역사 등 시대를 관통하는 주제도 함께 다루고 있습니다. 이번 서울국제도서전에서 아트레이크가 빚어낸 한국 미의 정수와 세상을 향한 통찰을 직접 만나보세요. 세계로 나아가는 우리 문화의 아름다운 여정에 여러분을 초대합니다. (www.artlake.co.kr)', 'http://www.artlake.co.kr', null, 163),
  (164, 'A2009', null, '좋은습관연구소', 'Good Habits Lab', null, null, false, array['사회과학']::text[], '좋은습관연구소는 ‘변화와 성장에 도움이 되는 개인과 기업의 좋은 습관’을 탐구하고 콘텐츠로 제안하는 지식 큐레이션 브랜드입니다. 우리는 거창한 성공 법칙보다 일상을 지탱하는 구체적인 ‘습관’의 힘에 주목합니다. 그동안 《반도체 애널리스트의 리서치 습관》, 《기술 성장주에 투자하는 습관》 등 실무적인 인사이트를 담은 도서부터, 최근에는 《AI 혁명을 이끈 천재들》, 《모든 것이 콘텐츠다》와 같이 인공지능과 IP 전략 등 시대의 변화를 읽어내는 안목을 제공하고 있습니다. 단순히 지식을 전달하는 것을 넘어, 독자의 삶에 즉각적인 변화를 만드는 ‘실천적 가이드’가 되는 것이 우리의 목표입니다. 우리는 오늘도 더 나은 내일을 만드는 작지만 단단한 습관들을 연구하고 기록합니다.', 'http://buildhabits.kr', 'https://www.instagram.com/build_habits/', 164),
  (165, 'A2009', null, '쥬쥬베북스', 'jujube books', null, null, false, array['예술','문학','아동']::text[], '더 나은 세상을 위한 다정한 단초를 모읍니다. 소박한 목소리에 귀 기울이며, 담대하고 옹골찬 출판을 지향합니다. 지난 4년간 성소수자, 돌봄, 환경 등 우리 사회에 꼭 필요한 이야기를 16권의 책에 담아왔습니다. 주요 도서로는 며느리와 시어머니의 교환 일기 (권현미, 윤여준), 계엄령과 민주주의를 그린 그래픽노블 (둘채), 순우리말을 그림으로 전하는 (이인아)가 있습니다. 올봄, 나무에게 지혜를 배우는 그림책 (오하나, 홍시야)를 출간해 큰 사랑을 받았으며, 이번 도서전에서는 정체성 고민과 관계의 너울 속에서 각자의 답을 찾아가는 청소년 희곡집 (강윤지)을 선보입니다.', 'http://studiojujube.com', 'https://www.instagram.com/notionhq/', 165),
  (166, 'A2009', null, '책과바람', 'Book&Wish Publisher', null, null, false, array['순수과학']::text[], '책과바람은 인문·과학 교양서를 펴내는 출판사로, 사이언스 큐레이션 [지속의 과학]과 에세이 큐레이션 [기억 갤러리]를 통해 지식과 공감의 흐름을 전합니다. 2026 서울국제도서전에서는 [지속의 과학] 시리즈의 첫 책 《얽힌 생명의 역사》(전방욱 저)와 두 번째 책 《물리학이 초대한 우주》(고재현 저)를 선보이며, 생명·우주·인간을 잇는 연결의 관점을 제안합니다. 책과바람은 ‘지속’·‘공존’·‘성찰’을 핵심 가치로 삼아, 삶을 깊고 의미 있게 확장하는 책을 만듭니다. 앞으로도 다양한 기획을 통해, 세계를 이해하는 지식과 자신을 되돌아보는 사유가 만나는 지점을 탐색하겠습니다. 그 만남이 독자의 삶에 새로운 생각의 길을 열기를 바랍니다.', null, 'https://www.instagram.com/booknwish_pub/', 166),
  (167, 'A2009', null, '한밤의빛', 'HANBAMBIT', null, null, false, array['철학','사회과학','예술']::text[], '사유의 밤을 밝히는 단단한 문장들, 보이지 않는 곳까지 닻을 내리는 책. 읽는 마음과 쓰는 마음이 포개지는 자리, ''한밤의빛''. 사진가 노순택의 『말하는 눈』, 건축가 승효상의 『솔스케이프』, 비평가 배형민의 『건축 너머 비평 너머』를 펴냈습니다.', null, 'https://instagram.com/hanbambit/', 167),
  (168, 'A2009', null, '허밍북스', 'HUMMINGBOOKS', null, null, false, array['문학']::text[], '안녕하세요, 출판사 허밍북스입니다. 허밍북스는 페이지를 넘기는 손길을 멈출 수 없게 만드는 장르 소설의 힘을 믿습니다. 그동안 독특한 감성의 일본 장르 문학을 국내 독자분들께 꾸준히 소개해 왔고, 이제는 그 영역을 영미권까지 넓혀 더욱 짜릿하고 거대한 서사를 준비하고 있습니다. 단순히 책을 내는 것을 넘어, 미스터리와 스릴러가 주는 서늘한 전율을 독자분들과 함께 나누고 싶습니다. 화려한 수식어보다 결국 끝까지 읽게 만드는 이야기가 궁금하시다면 허밍북스의 부스를 찾아주세요. 장르 소설을 사랑하는 사람들이 공들여 만든 책이 여러분을 기다리고 있습니다.', null, 'https://www.instagram.com/humming__books/', 168),
  (169, 'A2009', null, '호랑이꿈', 'Tigerdream Books', null, null, false, array['아동']::text[], '호랑이꿈은 20년 넘게 그림책을 만든 전문 편집자가 장인정신으로 정성껏 만드는 그림책 브랜드입니다. 단순히 책을 펴내는 것을 넘어, 지금 이 시대에 꼭 필요한 가치와 독창적인 시선을 담아내기 위해 매 권 치열하게 고민하고 완성합니다. 대표 도서로는 2024년 대한민국 그림책상 특별상을 수상한 『빠삐용』과 2025 화이트레이븐스(독일국립어린이청소년도서관 추천 도서) 선정도서 『나에게 주는 상』, 2024년 문화관광부 중소출판제작지원 선정작『과일 할아버지』 등입니다. 이번 서울국제도서전에서는 호랑이꿈의 뚝심과 철학이 고스란히 담긴 대표 도서들을 선보입니다', null, 'https://www.instagram.com/tigerdream_books/', 169),
  (170, 'A2009', null, '호손재', 'Hosonjae', null, null, false, array['총류','문학','전자출판']::text[], '[호손재 : From hand to story] “손끝에서 시작되어 마음 깊은 곳에 닿는 문장의 힘” 호손재는 문장의 힘을 믿습니다. 한국 근현대 문학의 정수를 복원하는 작업을 시작으로, 문학·에세이·인문 영역의 경계를 넘어 이를 ‘동시대 독자의 언어’로 새롭게 정의합니다. 호손재의 정체성은 독자의 사유와 손길을 거쳐 완성되는 ‘경험의 콘텐츠’에 있습니다. 100년 전 문인들의 예민한 숨결을 되살리는 필사집부터 일상의 지혜를 단단한 문장으로 엮어낸 교양서까지, 시대를 관통하는 텍스트를 발굴하여 당신의 삶에 닿는 가장 정성스러운 문장의 여정을 짓습니다. 소란한 세상 속에서 잠시 멈춰 문장을 음미하고 싶은 당신께, 호손재는 읽기와 쓰기가 공존하는 고요한 사유의 숲길이 되어드리겠습니다.', null, 'https://www.instagram.com/hosonjae_books/', 170),
  (171, 'A201', null, '안그라픽스', 'Ahn Graphics', null, null, false, array['총류','예술','학습참고서']::text[], '1985년 2월 안그라픽스는 한국 그래픽 디자인 역사를 새롭게 만들기 위한 크리에이티브 집단으로서 그 이념을 전파하고자 출판사를 함께 설립했습니다. 실험 정신, 끝없는 창의력, 지성이란 모토 아래 타이포그래피와 편집 디자인 분야를 개척해 왔으며, 디자인 출판 분야에서도 가장 전문적이고 창의적이며 비판적인 글과 세련된 디자인의 책을 만들어 왔습니다. 안그라픽스는 타이포그래피, 정보 디자인, 브랜드 디자인 및 건축, 예술, 에세이까지 다양한 분야의 좋은 책을 기획하고 출간합니다. 그뿐 아니라 한국 디자인의 정체성을 구축하는 작업과 디자인의 사회적 공공성을 실현하기 위한 연구, 그리고 출판에 힘씁니다.', 'http://www.agbook.co.kr', 'https://instagram.com/ahngraphics/', 171),
  (172, 'A2010', null, '주식회사 난다', 'Nanda', null, null, false, array['철학','예술','문학']::text[], '난다는 깊이 있는 이야기의 감각적 무장이라는 캐치프레이즈 아래 책 본연의 기능성과 가능성을 뛰어넘어 예술이 될 수 있는 책, 우리 문학과 문화의 동네에 역사로 남을 수 있는 책을 꿈꿉니다.', 'https://munhak.com/munhak/etc/all#brand', null, 172),
  (173, 'A202', null, '미디어버스', 'Mediabus', null, null, false, array['예술']::text[], '미디어버스는 2008년 서울에서 시작된 독립 출판사로, 예술과 시각문화, 비평을 다루는 책을 기획하고 출판해 왔습니다. 2010년부터는 서점이자 프로젝트 공간인 더북소사이어티를 운영하며, 국내외 예술 서적을 소개하고 전시, 강연, 북페어 등 다양한 프로그램을 함께 진행하고 있습니다. 출판과 공간 운영을 병행하며, 책을 중심으로 한 동시대 예술의 생산과 유통, 그리고 읽기의 장을 확장해 왔습니다.', 'http://mediabus.org', 'https://instagram.com/tbs_book_society/', 173),
  (174, 'A202', null, '사월의눈', 'Aprilsnow Press', null, null, false, array['예술']::text[], '2013년 사진책 출판을 시작한 사월의눈은 지금까지 총 30종의 사진책을 기획/발행했다. 디자인 저술가 전가경이 설립하고 이끄는 일인 독립 출판사이며, 북디자이너 정재완이 협력자로서 북디자인을 도맡고 있다. 2013년부터 대구에 근거지를 두고 있다. ‘수집’의 의미가 강한 ‘사진집’ 보다 ‘사진 + 책’이라는 두 매체의 교차와 접점 그리고 간극에 대한 생각을 자극하는 ‘사진책’이라는 용어를 선호하고 사용한다. 프로와 아마추어, 사진과 이미지, 사진과 영상, 전시와 책, 사진과 텍스트의 사이 공간을 탐색하고자 하며, 이 틈새를 연결짓는 행위로서 그래픽 디자인을 바라보고 있다.', 'http://www.aprilsnow.kr', 'https://www.instagram.com/aprilsnow_press/', 174),
  (175, 'A202', null, '프로파간다', 'propaganda', null, null, false, array['예술']::text[], '시각 문화 저널 과 대중 문화 단행본을 출간합니다. 2007년 출범, 독립출판 영역에서 활동하고 있으며 출판 외 전시 및 워크숍 등을 통해서도 새로운 어젠더를 탐색하고 토론하는데 열중하고 있습니다. 2021년 군산으로 근거지를 옮긴 이후에는 지역 출판 및 이벤트 등의 활동에 임하고 있습니다.', 'http://www.graphicmag.co.kr', null, 175),
  (176, 'A203', null, '인북', 'INBOOK', null, null, false, array['예술','문학','아동']::text[], '"75년의 깊이에 동시대의 감각을 더하다" 인북은 75년 역사를 지닌 대한민국 출판의 명가, (주)박영사의 단행본 임프린트입니다. 오랜 시간 인문, 사회과학 분야에서 쌓아온 단단한 지적 유산을 바탕으로 에세이, 경제경영, 실용 등 다양한 장르의 도서를 통해 지금 우리에게 필요한 이야기를 나누고 있습니다. 책을 매개로 한 진정한 소통을 지향하는 인북은 최근 2년 연속 서울국제도서전에 참가하여 유명 저자 사인회, 북토크 등 다양한 이벤트를 성료했습니다. 올해도 독자들과 가장 가까운 곳에서 만나, 우리 삶의 이야기를 책으로 소통하겠습니다.', 'http://blog.naver.com/inbook_py', null, 176),
  (177, 'A204', null, '안녕로빈', 'hellorobin', null, null, false, array['문학','아동']::text[], '안녕로빈의 상징인 로빈 새는 선물을 가져오는 전령입니다. 안녕로빈은 어린이와 청소년에게 인사하는 마음으로 책을 펴냅니다. 우리는 아동, 청소년기에 꼭 필요한 가치와 지식을 재미있는 이야기와 아름다운 그림으로 전하고, 학교 교육 과정과의 연계를 통해 배움을 확장하는 것을 목표로 합니다. 2018년 설립 이후 중학년 어린이 읽기 책 시리즈를 꾸준히 기획.출간해 왔으며, 해외 우수 그림책을 번역해 국내에 소개하고 있습니다. 최근에는 청소년 문학에 더욱 깊은 관심을 두고 출간을 이어가고 있습니다. 한국 어린이 출판연합, 한국 어린이 출판 콘텐츠 협회, 한국 청소년 출판협회 회원사이며 국내 주요 도서 지원 사업에 선정되고 있으며, 교육 관련 단체의 추천을 받은 우수 도서를 다수 보유하고 있습니다.', null, 'https://www.instagram.com/hellorobin_books/', 177),
  (178, 'A205', null, '킨더랜드+반달+여섯번째봄', 'KINDERLAND+BANDAL+THE SIXTH SPRING', null, null, false, '{}'::text[], null, null, null, 178),
  (179, 'A206', null, '(주)학토재', 'HAKTOJAE', null, null, false, array['사회과학','언어','학습참고서']::text[], '교육의 가치를 더하는 학토재입니다. 학토재는 학생지도, 교수법, 코칭 등 다양한 분야의 교육도서를출간하여 교육현장의 실질적인 노하우와 지식을 전달드리며,더불어 시각, 촉각 등을 활용하여 배움을 체득할 수 있는교육도구를 개발하여 현장중심의 살아있는 교육, 자연스럽고 재미있게 익힐 수 있는 교육을 위해 노력하고 있습니다.가르치는 분들께는 올바른 배움의 지도 방향을, 가르침을 받는학생들에게는 배움의 즐거움과 보람을 길러주는데 긍지를 갖고도구가 아닌 가치를 전하기 위해 나아갑니다.', 'https://happyedumall.com', null, 179),
  (180, 'A207', null, '노란상상', 'Noran Sangsang Books', null, null, false, array['아동']::text[], '노란상상은 2010년에 문을 연 어린이책 전문 출판사입니다. 사회와 우정, 용기, 이해, 나눔, 사랑, 철학 등 보편적이면서도 꼭 생각해 보아야 하는 다양한 주제의 책을 출간하고 있습니다. 눈으로만 읽는 것이 아닌 마음을 다해 읽는 책, 그럼으로써 생각하는 힘을 키워 줄 수 있는 책을 만들고자 노력합니다.', 'https://blog.naver.com/yyjune3', null, 180),
  (181, 'A208', null, '(주)도서출판보리', 'BORI', null, null, false, array['순수과학','아동','학습참고서']::text[], '보리는 1988년 아이들 그림책 전문 기획 집단 ''보리기획''에서 출발해 1991년 ''도서출판보리''로 출판등록을 하고 지금까지 교육의 철학과 전망을 보여 주는 책을 꾸준히 펴내고 있습니다. 보리가 펴내는 책에는 아이들이 어려서부터 생명을 존중하고, 세상을 과학적으로 인식하고, 이웃과 더불어 자유롭고 평등한 공동체 속에서 행복하게 살 길을 일러 주자는 철학이 담겨 있습니다. 대표작으로 우리 자연의 아름다움과 겨레의 살림살이를 보여 주는 그림책과 세밀화 도감, 대한민국 대표 어린이 사전으로 자리 잡은 과 창간 20주년에 빛나는 어린이 월간지 들이 있습니다. 보리는 이제까지 지켜 온 출판 철학을 앞으로도 이어 가며, 아이들과 교육을 살리는 좋은 책들을 더욱 열심히 펴내고자 합니다.', 'https://www.boribook.com/', null, 181),
  (182, 'A209', null, '니케북스', 'nikebooks', null, null, false, array['사회과학','문학','아동']::text[], '2010년 문을 연 니케북스는 수많은 독자에게 울림을 준 를 비롯해 과 등 독특한 주제의 인문 역사 교양 과학 책을 출간해 왔습니다. 또한, ''실존과 경계'', ''불멸의 연애'', ''환상과 마법'' 같은 문학 큐레이션 시리즈는 100년 전과 현재의 삶을 연결하고 있습니다. 니케북스는 생각을 유연하게 해주는 책을 좋은 책이라고 믿으며, 내용뿐 아니라 번역, 편집, 디자인까지 완성도 높은 도서를 만들기 위해 노력하고 있습니다. 니케주니어는 탄탄한 기획과 편집을 바탕으로 열두 살 궁그미를 위한 과학, 다판다 만물 트럭, 와글와글 인문학 수업 등 다양한 인문교양. 과학 시리즈를 통해 교과 과정에 필요한 지식과 교양을 갖춘 어린이를 위한 도서를 출간하고 있습니다.', 'https://blog.naver.com/nikebooks', null, 182),
  (183, 'A209', null, '목요일출판사', 'mokyoil', null, null, false, array['문학','아동']::text[], '한 그루의 나무가 품고 있는 소중한 가치를 담아 나무와 사람이 함께 만드는 따뜻한 이야기로 어린이와 어른이 함께 소통하고, 공감하는 책을 만듭니다. 예술의 한계를 뛰어 넘는 아이들의 상상력과, 굳건하게 살아온 어른들의 지혜를 담아 마음이 기억하는 책을 만들기 위해 한 걸음 한 걸음 걸어가고 있는 출판사입니다. # 철학과 예술이 함께 하는 책', 'https://blog.naver.com/mok_2015', null, 183),
  (184, 'A209', null, '페이퍼스토리', 'PAPERSTORY BOOKS', null, null, false, array['예술','문학','아동']::text[], '‘페이퍼스토리’는 “문화가 있는 삶, 행복한 책 읽기”를 모토로 일상의 소중한 가치를 담은 문학, 예술, 인문 교양서를 출간하고 있습니다. 문학과 음악, 미술, 영화, 사진, 건축 등 다양한 장르의 크로스오버를 시도하여 에세이, 교양서, 여행서, 실용서를 펴내고 있습니다. 상상력을 자극하는 책과, 공간과 사람, 일상의 소중함을 책에 담아 삶을 풍요롭게 해주는 책 만들기에 정성을 다합니다. 또한 텍스트로서 이미지를 활용한 도서를 제작하며 시각 이미지를 적극 활용해 눈으로 보고, 손으로 만지는 책의 물성을 감각적으로 체험하게 하는 것이 가장 큰 특징입니다. 페이퍼스토리의 출판하는 마음은 “어려운 것을 쉽게, 쉬운 것을 깊게, 깊은 것을 유쾌하게”를 지향하며 젊은 예술가들의 창조적인 출판 프로젝트와 새로운 작가들을 찾기 위해 끊임없이 노력합니다.', null, 'https://www.instagram.com/paperstory_book/', 184),
  (185, 'A210', null, '거북이북스', 'GOBOOKY BOOKS', null, null, false, array['문학','아동']::text[], '거북이북스는 만화처럼 즐거운 콘텐츠 전문 회사입니다. 2005년 만화, 동화, 그림책 등 도서를 근간으로 출판 사업을 시작, 디지털 콘텐츠로 사업 영역을 확대하며 브랜드 파워를 키워갑니다. 출판 사업은 철학적인 메시지가 담긴 그림책, 창의적인 스토리텔링의 동화책, 개성으로 튀는 만화책 등을 꾸준히 발행하면서 성장을 지속합니다. 디지털 콘텐츠 사업은 다양한 장르의 웹툰과 웹소설, E-book을 국내외 유명 플랫폼에 런칭하면서 차별화된 콘텐츠를 꾸준히 기획, 제작, 유통하고 있습니다. 오프라인 복합만화 공간 만화살롱 유어마나로 독립만화가들의 창작 활동을 지원하고, 독특한 만화 굿즈 시장을 풍성하게 이끕니다. 거북이북스는 고퀄리티의 문화 콘텐츠로 우리가 살아가는 세상을 더 즐겁고, 더 행복하게 만들어 나갑니다.', 'http://www.gobook2.com/', null, 185),
  (186, 'A2101', null, '사회평론', 'sahoipyoungnon', null, null, false, array['사회과학','예술','학습참고서']::text[], '사회평론은 1991년 설립됐습니다. ''용선생'' 시리즈와 같은 어린이 도서를 비롯해 난처한 시리즈 등의 인문 교양서, 국어교육, 사회복지학, 심리학 분야 등의 교재ㆍ학술서, ''Bricks''의 영어교육 도서들 등 다양한 분야의 책들을 출판하고 있습니다. 좋은 책, 아름다운 사람들. 사회평론은 좋은 책이 가지는 선한 영향력을 믿습니다.', 'https://sapyoung.com/', null, 186),
  (187, 'A2102', null, '오이뮤', 'OIMU', null, null, false, array['예술','문학']::text[], '오이뮤는 2015년부터 서울을 기반으로 활동하고 있는 출판사이자, 디자인 스튜디오입니다. 귀여운 마음으로 한국 정서와 문화를 잇는 디자인 활동을 하며, 도서 출판 및 다양한 매체를 활용한 제품 개발, 전시 등을 통해 디자인을 제안합니다.', 'https://oimu-seoul.com/', 'https://www.instagram.com/oimu_/', 187),
  (188, 'A2103', null, '은행나무', 'EunHaengNaMu', null, null, false, array['예술','문학','기타(인문학)']::text[], '은행나무는 시대와 미래를 읽는 책, 재미있고 감동 깊은 책을 모토로, 독자의 다양한 요구를 먼저 생각하는 열린 출판, 시대의 변화를 선도하는 젊은 출판, 좋은 콘텐츠와 정확한 지식정보를 전달하는 신뢰받는 출판을 지향합니다.', 'http://ehbook.co.kr', null, 188),
  (189, 'A2103', null, '(주)휴머니스트 출판그룹', 'Humanist Publishing Group', null, null, false, array['총류','사회과학','역사']::text[], '창립 25주년을 맞은 휴머니스트는 대한민국의 대표적인 지식․교양 출판사입니다. ‘가치 있는 삶의 동반자’를 기업 모토로 하여 2,400여 명의 국내 저자와 1,900여 종의 책을 출간하였습니다. 인문적인 소양을 토대로 역사, 철학, 사회과학, 예술, 자연과학 등 지식의 전 영역에서 탄탄한 교양서와 학술서 발간하고, 인류의 지적 유산인 고전의 현대적 출판을 주도하고 있습니다. 2006년에 ‘휴먼 어린이’를 자회사로 설립하였고, 2017년 오늘이 행복해지는 라이프스타일을 제안하는 ‘자기만의 방’을, 2021년 Z세대 청소년을 위한 ‘곰곰’을, 2022년에는 큐레이션 세계문학 ‘흄세(휴머니스트 세계문학)’를 선보이며 세대별･분야별 관심을 충족시키는 다양한 시리즈 브랜드로 독자의 삶에 다가서고 있습니다.', 'http://www.humanistbooks.com', 'https://www.instagram.com/_jabang/', 189),
  (190, 'A2201', null, '길벗어린이', 'Gilbut Children Publishing', null, null, false, array['예술','문학','아동']::text[], '길벗어린이는 1995년 설립 이래, 대한민국 그림책 시장의 기반을 만들어 온 어린이 전문 출판사입니다. 어린이를 위한 책이기 때문에 오히려 더 정교하고 세심하게 만들어야 한다는 믿음으로 책 한 권 한 권을 기획합니다. 단순히 정보를 전달하는 것이 아니라 삶에 대한 깊은 통찰과 정서적 울림을 전할 수 있는 콘텐츠를 만들어야 한다는 책임감이 우리의 출발점입니다. 그림책은 단순한 교육 콘텐츠를 넘어, 삶에 대한 통찰과 정서적 울림을 전하는 이야기를 담고 있는 예술의 한 장르로 뻗어나가고 있습니다. 그림 한 장, 문장 하나에도 오래 남을 진심을 담고자 하며, 독자가 책을 덮은 후에도 마음에 오래 남는 경험을 전하는 것을 목표로 합니다.', 'http://www.gilbutkid.co.kr', null, 190),
  (191, 'A2202', null, '문학과지성사', 'Moonji Publishing Co., Ltd', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '문학과지성사는 1975년 12월, 문학과지성 동인을 함께한 김병익, 김주연, 김치수, 김현 비평가와 1세대 인권 변호사로서 헌신했던 황인철 변호사가 힘을 합쳐 설립하였습니다. 문학과지성사가 특정 개인의 소유가 아니라 ''문학적 공동체''의 것이라는 생각은 창립 초기부터 시작되었습니다. 문학의 자율성과 문학의 공공성, 그리고 인문적 지성의 존중을 회사의 가치로 만들어가고자 했습니다. 그로부터 50년이 된 지금까지 문학과지성사는 한국 사회에 대한 깊은 성찰을 촉발하는 문학과 인문학 저서들을 지속적으로 발간해왔습니다. 문지시인선과 소설 등 문학 작품뿐만 아니라, 출판의 영역을 넓혀 약 3,000종의 문학, 인문, 학술, 청소년, 아동 분야의 서적들을 발행하고 있습니다.', 'http://www.moonji.com', 'https://www.instagram.com/moonji_books/', 191),
  (192, 'A2203', null, '소전문화재단', 'Sojeon Foundation', null, null, false, array['문학']::text[], '우리의 일(業)은 사람들이 책을 읽도록 장려하는 것입니다. 사회와 자신의 관계를 이해하려는 정신적 작업인 문학을 통해 인간다운 삶에 대한 성찰과 자각이 가능하다고 믿습니다. 우리의 목표는 독서를 통하여 사람들이 지극히 좋은 상태(至善)에 도달하도록 돕는 것입니다.', 'https://www.the-reader.or.kr', null, 192),
  (193, 'A2301', null, '서울특별시교육청', 'Seoul Metropolitan Office of Education', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '서울특별시교육청은 서울시의 유아, 초등, 중등 교육을 총괄하는 지방교육행정기관으로서 1956년 설립되었습니다. 우리는 2026년 현재 ''미래를 여는 협력교육''을 비전으로 삼고, 학생들이 스스로 미래를 열어가는 역량을 갖출 수 있도록 지원하고자 합니다. 이를 위해 교육공동체의 모든 구성원들과 시민들이 공동의 책임을 가지고 참여와 소통, 자치와 협력, 협력적 문제 해결을 통해 교육을 실천해 나가는 서울교육을 지향하고 있습니다.', 'https://www.sen.go.kr/sen/index.do', 'https://www.instagram.com/now_seouledu/', 193),
  (194, 'A2302', null, '마음산책', 'MAUMSANCHAEK', null, null, false, array['예술','문학']::text[], '2000년에 출범한 마음산책은 시와 소설, 산문을 포괄하는 문학의 공간, 세상에 대한 통찰이 번뜩이는 글을 통해 사유의 폭 넓히기를 지향하는 지혜의 공간, 문화의 향유를 통해 삶의 즐거움을 누린다를 모토를 갖고 펴내는 문화의 공간 등의 영역을 갖고 문학, 예술, 인문도서를 출판하고 있다. 마음산책은 기획 개념이 돋보이는 문학서, 이야기가 담긴 예술서, 인문서를 지향하면서 출판의 새로운 트렌드를 만들어나가고자 한다.', 'http://maumsan.com', null, 194),
  (195, 'A2302', null, '사계절출판사', 'SAKYEJUL', null, null, false, array['사회과학','문학','기타(그림책)']::text[], '사계절출판사는 1982년 6월 1일, 시대정신을 실현하는 인문사회과학 전문 출판사로 설립되었습니다. 사계절출판사는 앞으로도 한국의 역사와 문화를 재조명하는 인문학 도서를 비롯해 성장의 의미를 생각하는 유년·아동·청소년 도서를 꾸준히 펴낼 것이며, ‘책이라는 그릇에 시대정신을 담는다’는 사명감으로 ‘오래 갈수록 빛을 더하는 책’을 만들기 위해 정성을 다할 것입니다. 대표도서로, 『임꺽정』(전10권), ‘한국생활사박물관’ 시리즈, 『누가 내 머리에 똥 쌌어?』, 『마당을 나온 암탉』, 『어린이라는 세계』, ‘민주인권그림책’ 시리즈 등이 있습니다.', 'http://www.sakyejul.net', null, 195),
  (196, 'A2303', null, '디자인하우스', 'Designhouse', null, null, false, array['사회과학','예술','기타(잡지)']::text[], '1976년에 창립한 디자인하우스는 단행본과 4종의 월간지 , , , 을 출간하며, 온라인 플랫폼 과 을 운영하고, 서울리빙디자인페어(SLDF), 서울디자인페스티벌(SDF)을 비롯한 국내 최대 규모 전시를 주관하는 종합 미디어 기업입니다. 특히 디자인하우스 단행본 출판부에서는 "Design your workstyle and lifestyle"을 모토로, 브랜드&트렌드, 라이프스타일&디자인을 주제로 하는 다양한 책을 만들고 있습니다. 주요 도서로는 , , , , 등이 있습니다.', 'https://www.designhouse.co.kr', 'https://www.instagram.com/stylehmag/', 196),
  (197, 'A2303', null, '주식회사 오뚜기', 'OTOKI Corporation', null, null, false, array['기타(푸드에세이','브랜드북 등)']::text[], '주식회사 오뚜기는 국민의 식생활을 향상시키고자 하는 신념으로 1969년에 설립된 우리나라를 대표하는 종합 식품 기업입니다. 카레, 스프, 마요네스, 라면 등 시대를 선도하는 혁신적인 식품들을 제조·판매하며 우리 국민의 식탁 위를 책임져 왔습니다. 보다 좋은 품질, 보다 높은 영양, 보다 앞선 식품을 위해 노력하는 오뚜기는, 이제 나아가 인류의 식생활 향상과 건강을 증진하고자 합니다. 그리고 맛있고 든든한 음식에서 비롯된 행복이 가정과 사회로 퍼져 나가기를 바라는 ‘스위트홈’의 가치를 담아 고객과 소통합니다.', 'https://www.otoki.com/', 'https://www.instagram.com/otoki_daily/', 197),
  (198, 'A2401', null, '타이베이도서전재단', 'Taipei Book Fair Foundation', '타이완', 'Taiwan', false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], 'The Taipei Book Fair Foundation (TBFF) was established in 2004 by 18 leading Taiwanese publishers to support the long-term development of the Taipei International Book Exhibition (TIBE) and the publishing industry. As the official organizer of TIBE from 2005 to 2026, TBFF promotes international publishing exhcange and creates cultural and business opportunities for publishers from Taiwan and around the world, while also encouraging public engagement with reading and books.', 'http://taipeibookfair.org/en/', 'https://www.instagram.com/tbff_tibe/', 198),
  (199, 'A2402', null, '책만남홀1', 'Readers Hall 1', null, null, true, '{}'::text[], null, null, null, 199),
  (200, 'A301', null, '워크룸 프레스', 'Workroom Press', null, null, false, array['예술','문학','기타(디자인)']::text[], '워크룸 프레스는 2006년 설립 이래 디자인 스튜디오를 운영하면서 미술, 디자인, 문학, 인문, 음악, 패션 분야의 책을 출간해 왔습니다. 2013년부터 슬기와 민과 함께 임프린트 작업실유령을 공동 운영하고 있습니다.', 'https://workroompress.kr/', 'https://www.instagram.com/workroompress/', 200),
  (201, 'A302', null, '산지니', 'Sanzini', null, null, false, array['사회과학','문학','아동']::text[], '산지니는 가장 높이 날고 오래 버티는 우리나라의 전통 매를 말하는 것으로, 척박한 지역출판의 환경 속에서 오래 버티고자 하는 바람을 담고 있습니다. 산지니는 설립 당시 세 가지 목표와 함께 출발했습니다. 첫째, 문화의 지역화와 문화민주주의의 심화에 일조하기. 둘째, 쉽게 읽을 수 있는 책을 만들기. 셋째, 이 땅에 사는 사람들의 행복에 도움이 되는 책을 출간하기. 이러한 바람 속에서 산지니는 2005년 설립 이후 현재까지 인문, 사회, 정치, 문학 등 다양한 분야에서 900여 종의 단행본을 발간했으며, 2012년에는 문화체육관광부 표창을, 2015년에는 한국출판학회로부터 경영, 영업 부문 대상을 수상하였습니다.', 'http://www.sanzinibook.com/', null, 201),
  (202, 'A303', null, '(주)까치글방', 'Kachi Publishing Co., Ltd.', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '한국의 현대사가 격동의 드높은 분수령을 넘고 한국 사회의 명암이 교차하던 1970년대 말에 문을 열었습니다. 까치글방은 인문학, 사회과학, 자연과학의 세계적 고전과 현대 석학들의 저서들을 집중적으로 번역 출간하여, 일반 독자와 학계의 관심을 고조시켰습니다. 또한 다양한 분야의 도서를 국내에 소개하여 독자의 시야를 넓히고, 인접 학계의 연구에 보탬이 되었습니다. 1990년대 중반부터 전문가는 물론 일반 대중도 즐길 수 있는 물리학, 수학, 동식물학 분야의 도서 보급에 앞장서서 자연과학의 대중화에 선도적인 역할을 했습니다. 쉴 틈 없이 변하는 세상 속에서 오직 독자만을 생각하며 이 시대가 요구하는 틈을 채우기 위해 묵묵하게 걸어가겠습니다.', 'https://www.kachibooks.co.kr/', 'https://www.instagram.com/kachibooks/', 202),
  (203, 'A304', null, '글항아리', 'GEULHANGARI', null, null, false, array['철학','사회과학','역사']::text[], '글항아리는 고전에서 학문의 최전선, 실용에서 문학까지 다양한 양서들을 펴내는 출판사입니다. 2007년 창립 이래 인문학과 사회과학에 집중하면서 과학, 예술에 이르기까지 여러 분야에 걸쳐 900여 권의 책을 펴냈고, 토마 피케티의 21세기 자본을 비롯해 동양고전 시리즈, 걸작 논픽션, 현대의 고전 시리즈, 규장각 교양총서 등 주목받는 시리즈도 꾸준히 펴내왔습니다. 영역을 더 확장하기 위해 에쎄와 파불라, 글항아리사이언스도 함께 운영하고 있습니다. 일상의 작은 것 하나 놓치지 않고 종이에 적어 항아리 단지에 보관해두었다는 연암 박지원의 일화에서 따온 글항아리라는 이름에 걸맞게 지치지 않고 의미 있는 글을 발굴하며 출간하는 데 힘쓰고자 합니다.', 'http://geulhangari.com', 'https://www.instagram.com/bookpot/', 203),
  (204, 'A305', null, '청아출판사 / 봄마중', 'ChungA Publishing Co.', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '청아출판사는 1979년 설립된 이래 역사, 예술, 인문, 과학, 아동 분야의 책을 두루 출판하고 있습니다. 쉽게 읽을 수 있는 역사책, 감동과 재미를 동시에 주는 교양책, 지식을 전달하는 과학책 등 정신을 살찌우는 양서를 만드는 데 주력합니다. 청아출판사의 자회사로는 아동을 위한 고전을 소개하는 도서출판청솔, 창의력과 사고력을 길러주는 브랜드 봄마중이 있습니다.', null, 'https://www.instagram.com/chunga_book/', 204),
  (205, 'A306', null, '도서출판 풀빛', 'Pulbit', null, null, false, array['총류','사회과학','아동']::text[], '도서출판 풀빛은 바른 사회를 향한 밑거름이 되고자 1979년 3월 6일에 문을 열었습니다. 풀빛은 짓밟혀도 일어서는 풀의 강인한 생명력과 어둠을 밝히는 빛으로 희망이 가득한 세상을 열어 간다는 의미를 담고 있습니다. 초창기, 풀빛은 사회과학 서적을 중심으로 교양, 문학, 교육 서적 등 다양한 분야의 책을 출간해 독자들로부터 많은 사랑을 받았습니다. 2000년대에는 새로운 지평을 열었습니다. 좋은 책이 좋은 사람을 만든다는 신념으로 어린이와 청소년을 위한 책을 출판하기 시작했습니다. 지금은 어린이와 청소년을 위한 그림책, 소설, 논픽션을 출판하고 있습니다. 앞으로도 좋은 책이 좋은 사람을 만든다는 정신으로 출판에 최선을 다하고자 합니다.', 'https://www.pulbit.co.kr/', 'https://www.instagram.com/pulbitkids/', 205),
  (206, 'A307', null, '도서출판 푸른숲', 'PRUNSOOP publisher', null, null, false, array['사회과학','문학','아동']::text[], '1988년에 설립된 푸른숲은 세상에 기여할 수 있는 가치와 양식을 담은 출판을 지향합니다. 인문교양서를 중심으로 문학, 사회과학, 자기계발, 어린이청소년 등 다양한 분야의 책을 내는 종합출판사입니다. , , 등 30여 년간 독자들에게 따뜻한 위안과 영감, 희망을 건네왔습니다. 을 쓴 위화 작품을 국내에 독점 소개해왔으며, , 등 시대정신을 담은 자기계발서도 활발히 펴내고 있습니다. 또한, , 등을 펴내며 명실상부 최고의 심리 전문 브랜드 자리매김한 심심과 , 등 라이프스타일 브랜드 벤치워머스를 전개하고 있습니다.', 'http://www.prunsoop.co.kr', 'https://www.instagram.com/prunsoop/', 206),
  (207, 'A308', null, '(사)한국과학기술출판협회', 'Korean Science & Technology Publishers Association', null, null, false, array['기타(과학기술출판사)']::text[], '(사)한국과학기술출판협회는 1988년 과학기술부 인가로 출판산업 발전과 과학기술 독서 보급 및 과학 기술 독서 인구의 저변 확대를 위해 설립된 단체입니다. 과학기술의 발전과 과학기술 출판을 통하여 저술인의 발굴 및 전문 인력양성 등 국가 발전에 기여 하기위해 노력하고 있습니다.', 'http://www.kstpa.or.kr', null, 207),
  (208, 'A308', null, '군자출판사', 'KOONJA Publishing Inc.', null, null, false, array['기술과학','문학','아동']::text[], '군자출판사는 의학, 치의학, 한의학, 간호학 등 다양한 분야에서 약 3,000종의 의학 서적을 출간한 국내 최고의 의학 전문 출판사입니다. 현재는 오랫동안 쌓아온 우수한 의학 콘텐츠를 바탕으로 아동 도서와 일반 단행본 분야까지 사업 영역을 확장하며 종합 출판사로 성장했습니다. 전문적인 의학 지식을 누구나 쉽게 이해할 수 있도록 아동 및 청소년을 위한 의학 교육 도서와 일반 독자들을 위한 다양한 건강 서적 등 폭넓은 콘텐츠를 출간하고 있으며, 국내 의료진 및 관련 기관들과의 긴밀한 협력을 통해 정확하고 신뢰할 수 있는 콘텐츠 개발을 지속적으로 추진하고 있습니다.', 'http://www.koonja.co.kr', null, 208),
  (209, 'A401', null, '보림출판사', 'BORIMPRESS', null, null, false, array['아동']::text[], '보림출판사는 1976년 설립되어 그동안 독자적인 예술 장르로서의 그림책 세계를 소개해 왔습니다. 한국 현대 그림책 역사와 시작을 함께하며, 해외의 좋은 책을 소개하는 한편 옛이야기와 전통문화를 아우르는 콘텐츠를 개발하고 국내 작가들의 창작 그림책을 꾸준히 출간해 왔습니다. 1999년부터 진행된 보림창작그림책 공모전과 보림그림책창작스튜디오를 통해 국내 그림책 작가를 양성하고 우리 창작 그림책의 영역을 넓혀 가고자 노력하고 있습니다.', 'http://www.borimpress.com', null, 209),
  (210, 'A402', null, '네이버웹툰', 'NAVER WEBTOON', null, null, false, array['문학','전자출판']::text[], '매일매일 새로운 재미, 가장 가까운 즐거움을 만듭니다. 한국을 대표하는 검색 포털 네이버의 작은 서비스 중 하나로 시작한 네이버웹툰은 기존 만화 시장의 창작과 소비 문화 전반을 혁신하고 이전에 없었던 창작 생태계를 만들어왔습니다. 또한 네이버웹툰은 변화하는 트렌드에 발맞춰 강력한 콘텐츠를 선보이는 한편 이제는 한국을 넘어 전세계의 작가들과 독자들이 즐겁게 만날 수 있는 글로벌 스토리테크 플랫폼으로 도약하였습니다. 네이버웹툰의 항해는 여기서 그치지 않고 출판, MD, 영상, 게임 등 다양한 콘텐츠로 그 영역을 확장하며 이야기의 힘과 가치를 더욱 증폭시키고자 합니다. 이를 통해 스크롤 너머의 또 다른 감동과 다채로운 경험을 독자분들께 선사하겠습니다.', 'https://comic.naver.com/index', null, 210),
  (211, 'A403', null, '(주)위즈덤하우스', 'WISDOMHOUSE', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '우리는 한국에서 가장 독자 중심적인 출판사로서 독자들이 현재를 살아가는 데 필요한 보편적 필요부터 세부적인 취향까지 다양한 콘텐츠를 제공합니다. 필요한 지식과 정보, 문화가 담긴 완성도 높은 단행본 출판은 물론 재미와 감동을 주는 웹툰과 웹소설을 서비스하며, 이를 기반으로 드라마, 영화, 방송, 애니메이션 등 다양한 미디어와 연계하여 더 즐거운 가치를 만듭니다.', 'https://www.wisdomhouse.co.kr/', 'https://www.instagram.com/wisdomhouse_official/', 211),
  (212, 'A501', null, '이야기장수', 'STORYSELLER', null, null, false, array['문학']::text[], '이야기장수는 문학동네의 계열사로 스타편집자인 이연실 편집자가 이끌며 최근 이슬아, 김하나, 황선우 작가의 책을 영미권과 유럽의 세계적인 출판사에 수출한 출판사입니다. 솔테라이브러리는 이야기장수와 (주)소금도서관이 힘을 합쳐 2026년 4월 런칭하는 서점(서점업 등록완료)이자 책과 문학을 모티브로 조향한 향수를 만드는 향수전문점입니다. 2026년 북촌, 홍대, 성수까지 젊은이들과 해외관광객들이 모이는 핫플레이스에 오프라인 3개 매장을 내고, 대한민국의 책과 향을 동시에 알리는 새로운 브랜드를 만들어갑니다. 우리는 향기는 가장 순간적이고 직관적인 문학이고, 문장은 가장 오래 남는 향기라 믿습니다. 책과 향의 가장 아름다운 만남을 꿈꿉니다.', null, 'https://www.instagram.com/promunhak/', 212),
  (213, 'A501', null, '솔테라이브러리', 'Salté Library', null, null, false, array['문학']::text[], '솔테라이브러리(Salté Library)는 향과 문학이 만나는 프래그런스 하우스입니다. 우리는 향을 단순한 향기가 아니라 읽을 수 있는 경험으로 만듭니다. 각 향수는 하나의 이야기를 담고 있으며, 각 향은 한 편의 문학처럼 구성됩니다. 솔테라이브러리는 향을 통해 사람들의 기억과 순간을 기록하는 향의 도서관을 지향합니다. 솔테라이브러리는 향을 하나의 문학적 언어로 바라봅니다. 어떤 향은 한 사람을 떠올리게 하고, 어떤 향은 한 계절을 기억하게 합니다. 그래서 우리는 향을 하나의 이야기처럼 구성합니다. 각 향수는 하나의 장면이며, 각 향은 하나의 서사를 담고 있습니다. 솔테라이브러리는 작가 협업 향수와 자체 향수 컬렉션을 함께 전개합니다. 향수 라인은 문학적 세계관을 기반으로 개발되며 각 향은 하나의 이야기와 감정을 담고 있습니다.', 'https://www.saltelibrary.com/', 'https://www.instagram.com/saltelibrary.official/', 213),
  (214, 'A502', null, '(주)김영사', 'Gimmyoung Publishers', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '김영사는 ''행복한 마음'' 입니다 더 오래 지혜를 전합니다 더 깊이 오늘을 읽습니다 더 넓게 세계와 만납니다 우리가 누리는 세계 우리가 만드는 오늘 우리가 꿈꾸는 미래 독자는 행복을 만들고 누리고 꿈꿉니다 김영사는 행복한 책으로 함께합니다', 'http://gimmyoung.com', 'https://www.instagram.com/gimmyoung/', 214),
  (215, 'A503', null, '(주)문학수첩', 'MoonhakSoochup', null, null, false, array['순수과학','예술','문학']::text[], '(주)문학수첩은 1991년 창립한 이래, 책으로 전하는 사랑이라는 모토 아래 우리 출판문화를 선도해온 종합출판사입니다. 세계적인 베스트셀러 시리즈를 비롯하여, 댄 브라운의 , , , , 국내 최초의 무삭제 완역판 를 펴냈으며, 그 밖에도 제임스 대시너, 할런 코벤, 마크 해던 등 국내외 유명 작가들의 책들을 출간하고 있습니다. 특히 (J.K.롤링 저) 시리즈는 1999년 출간 이후 성인뿐 아니라 아동 출판 시장에서 주도적인 위치를 점유하고 있습니다. 이 시리즈는 아이들에게 책 읽는 습관을 되찾아준 의미 깊은 도서로 자리매김하였습니다.', 'http://moonhak.co.kr/', 'https://www.instagram.com/moonhaksoochup/', 215),
  (216, 'A601', null, '주한프랑스대사관 문화과', 'Embassy of France in the Republic of Korea', '프랑스', 'France', true, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], 'The Cultural Service of the Embassy of France in the Republic of Korea is responsible for implementing cooperation actions between France and Korea in order to promote artistic, cultural, and academic exchanges as well as the practice of the French language. The Cultural service of the Embassy of France in Korea partners with major Korean cultural festivals and artistic institutions, and supports the invitation of French writers and scholars. It also operates publication and translation support program for Korean publishers who want to publish French books.', 'http://kr.ambafrance-culture.org/ko/#/', 'https://www.instagram.com/franceencoree_culture/', 216),
  (217, 'A601', null, '프랑스 출판네트워크 (구 : 프랑스국제출판사무국)', 'France Livre (formerly BIEF)', '프랑스', 'France', true, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '프랑스 리브르 (France Livre)는 약 350여 개 프랑스 출판사의 해외 진출을 지원하는 프랑스 출판 네트워크입니다. 소속 출판사들은 주요 국제 도서 박람회에 참여하며, 프랑스와 해외 도서 산업의 주요 관계자들 간의 다양한 전문가 회의를 주선하기도 합니다. 또한 국제 출판 시장에 대한 연구 자료도 발간하고 있습니다.최근에는 회원 출판사들의 최신 소식을 주제, 편집 카테고리, 출판사, 저자별로 검색할 수 있는 새로운 플랫폼을 선보였습니다 : www.booksfromfrance.fr', 'http://www.booksfromfrance.fr', null, 217),
  (218, 'A602', null, '(주)쌤앤파커스', 'Sam & Parkers Co., Ltd.', null, null, false, array['문학','아동','기타(자기계발','경제경영)']::text[], '쌤앤파커스는 2006년 설립되어 올해로 20주년을 맞은 출판사로, 경제경영과 자기계발 분야를 중심으로 독자들의 삶에 실질적인 변화를 제안하는 콘텐츠를 만들어왔습니다. 『달러구트 꿈 백화점』, 『초격차』, 『멈추면 비로소 보이는 것들』, 『아프니까 청춘이다』 등 시대를 관통하는 베스트셀러를 통해, 빠르게 변화하는 환경 속에서 필요한 통찰과 방향성을 제시하며 출판 시장을 선도해왔습니다. 또한 올리, 팩토리나인, 비에이블, 노바코믹스 등 다양한 브랜드를 동해 소설, 아동, 에세이, 실용, 아동, 코믹스까지 영역을 확장하며 폭넓은 독자층과 소통하고 있습니다. 앞으로도 쌤앤파커스는 변화하는 시대를 가장 먼저 읽고, 독자에게 꼭 필요한 콘텐츠를 가장 의미 있는 방식으로 전달하며, 설렘과 즐거움, 감동과 자부심을 전하는 출판사를 지향합니다.', 'http://www.samnparkers.com', 'https://www.instagram.com/samnparkers/', 218),
  (219, 'A701', null, '봄알람', 'baumealame', null, null, false, array['철학','사회과학','문학']::text[], '올해 10주년을 맞이하는 페미니즘 출판사입니다. 성차별적 현실에 개입하고, 여성들의 목소리에 힘을 실으며, 여성이 인간으로서 살아갈 상상력을 주는 책을 펴냅니다. 성평등 교육과 직장 내 성차별 같은 사회 보편의 문제부터 낙태죄, 대리모, 성매매와 같은 신체 기본권 문제, 여성운동의 역사와 인물을 다룬 책까지 폭넓게 출간합니다. 과 등 베스트셀러를 냈습니다. 페미니즘 지식이 내게 힘이 되는, 즐거운 경험임을 널리 알리고 싶습니다.', 'http://baumealame.com', null, 219);
